WITH base AS (SELECT *, CONCAT(method, ', ', status) AS method_status, COALESCE(method, 'NONE') AS resolved_method FROM payments WHERE order_id IS NOT NULL AND method IS DISTINCT FROM 'card') SELECT p.channel, a.status AS payment_status, COUNT(*) AS rows_total, AVG(a.amount) AS avg_amount, GROUPING_ID() AS gid FROM base a LEFT JOIN orders p ON a.order_id = p.id GROUP BY GROUPING SETS ((p.channel, a.status), (p.channel)) ORDER BY rows_total NULLS FIRST;
